/* SPDX-License-Identifier: GPL-3.0-only
 * Task 2.10 fix round (ported from tests/klee/wasm.c of the legacy KLEE
 * route): the --wasm mode of Map2Check under symex. wasm.wat lifted by
 * wasm2c (t.h/t.c, generated by the test), driven like the wrapper of
 * caller.cpp generateWasmWrapperStatic (wasm_rt_init, instantiate, _start,
 * free), linked in the memtrack mode with WasmRuntimeStubs.bc. Expected in
 * both runtimes: the write one int past the 40-byte block is OVERFLOW at
 * line 0 with no function (SD-19), found by KLEE as an abort. */
#include <stdint.h>
#include "t.h"

void map2check_init(int);
void map2check_success(void);
void map2check_wasm_malloc(uint64_t offset, uint64_t size);
void map2check_wasm_check_access(uint64_t offset, uint64_t access_size);

/* The two calls MemoryTrackPass -wasm-mode inserts, as the module's imports. */
void w2c_env_track(struct w2c_env *env, u64 offset, u64 size) {
  (void)env;
  map2check_wasm_malloc(offset, size);
}
void w2c_env_check(struct w2c_env *env, u64 offset, u64 size) {
  (void)env;
  map2check_wasm_check_access(offset, size);
}

int __map2check_main__(int argc, char **argv) {
  (void)argc; (void)argv;
  map2check_init(0);
  w2c_t instance;
  wasm_rt_init();
  wasm2c_t_instantiate(&instance, (struct w2c_env *)0);
  w2c_t_0x5Fstart(&instance);
  wasm2c_t_free(&instance);
  wasm_rt_free();
  map2check_success();
  return 0;
}
